//! M3-14 acceptance: the overview answers in under 300 ms with 10,000 devices and 100,000
//! rows per audit table, on SQLite, through the whole stack (gate, queries, view); enforced
//! exactly with `DESKHAVEN_PERF_STRICT=1`, loosely otherwise (see [`budget`]). The data
//! is generated by the database itself (one `INSERT .. SELECT` per table). PostgreSQL runs
//! the same query for its answers only: its timing depends on the machine and the server.
#![allow(clippy::unwrap_used, clippy::panic, clippy::print_stderr)]

mod common;

use std::net::{IpAddr, Ipv4Addr};
use std::time::{Duration, Instant};

use common::{Harness, harness};
use deskhaven_admin_api::AdminRoutes;
use deskhaven_core::users::Role;
use deskhaven_db::testing::{Backend, TestDb, each_migrated_backend};
use deskhaven_db::time;
use sea_orm::ConnectionTrait;

const DEVICES: i64 = 10_000;
const ROWS: i64 = 100_000;
const ONLINE: i64 = 2_000;
const BUDGET: Duration = Duration::from_millis(300);
/// A shared machine (CI runners, parallel builds) slows every query alike, so by default the
/// test only catches gross regressions (a lost index costs seconds, not a few hundred ms).
/// `DESKHAVEN_PERF_STRICT=1` holds the query to the exact acceptance budget.
const LOADED_FACTOR: u32 = 4;
const STRICT_ENV: &str = "DESKHAVEN_PERF_STRICT";

fn budget() -> Duration {
    match std::env::var(STRICT_ENV).as_deref() {
        Ok("1") => BUDGET,
        _ => BUDGET * LOADED_FACTOR,
    }
}
const OVERVIEW: &str = "/admin/api/v1/overview";
/// Rows are spread over this many seconds before now (two days, so half are in the window).
const SPREAD_SECS: i64 = 172_800;
/// Each query runs this many times and the fastest counts: one slow run is the machine, not
/// the query.
const RUNS: usize = 3;

fn generate(table: &str, columns: &str, values: &str, rows: i64) -> String {
    format!(
        "WITH RECURSIVE n(i) AS (SELECT 1 UNION ALL SELECT i + 1 FROM n WHERE i < {rows}) \
         INSERT INTO {table} ({columns}) SELECT {values} FROM n"
    )
}

fn statements(backend: Backend, now: i64) -> Vec<String> {
    let created = format!("{now} - (i % {SPREAD_SECS}) * 1000");
    let bytes = match backend {
        Backend::Sqlite => "CAST('u' || i AS BLOB)",
        _ => "CAST('u' || i AS BYTEA)",
    };
    vec![
        generate(
            "devices",
            "rustdesk_id, uuid, pk, version, status, first_seen_at, last_seen_at, last_ip, \
             register_ip, register_at, created_at, updated_at",
            &format!(
                "'dev' || i, {bytes}, {bytes}, CASE WHEN i % 20 = 0 THEN NULL \
                 ELSE '1.' || (i % 40) || '.' || (i % 7) END, 'active', {now}, {now}, \
                 '192.0.2.1', '192.0.2.1', {now}, {now}, {now}"
            ),
            DEVICES,
        ),
        generate(
            "connection_sessions",
            "guid, device_rustdesk_id, conn_id, session_id, peer_rustdesk_id, peer_name, \
             conn_type, created_at",
            &format!(
                "'g' || i, 'dev' || (i % {DEVICES}), i, '' || i, 'p' || (i % 1000), 'peer', i % 5, {created}"
            ),
            ROWS,
        ),
        generate(
            "alarms",
            "device_rustdesk_id, typ, info, conn_id, created_at",
            &format!("'dev' || (i % {DEVICES}), i % 11, '{{\"name\":\"x\"}}', i, {created}"),
            ROWS,
        ),
        generate(
            "login_events",
            "username_attempted, method, result, client, created_at",
            &format!(
                "'name' || (i % 1000), 'password', \
                 CASE WHEN i % 3 = 0 THEN 'success' ELSE 'invalid_credentials' END, \
                 CASE WHEN i % 2 = 0 THEN 'console' ELSE 'rustdesk' END, {created}"
            ),
            ROWS,
        ),
    ]
}

async fn seed(h: &Harness, backend: Backend) {
    let now = time::now().timestamp_millis();
    for sql in statements(backend, now) {
        h.state.db.execute_unprepared(&sql).await.unwrap();
    }
    let presence = h.state.devices.presence();
    let ip = IpAddr::V4(Ipv4Addr::new(192, 0, 2, 7));
    for i in 1..=ONLINE {
        presence.heartbeat(&format!("dev{i}"), ip, &[1, 2]);
    }
}

#[tokio::test]
async fn the_overview_over_10k_devices_and_100k_audit_rows_answers_within_the_budget() {
    each_migrated_backend(async |db: &TestDb| {
        let h = harness(db, AdminRoutes::new()).await;
        let admin = h.console("adm", Role::Admin).await;
        seed(&h, db.backend).await;

        let mut fastest = Duration::MAX;
        let mut body = serde_json::Value::Null;
        for _ in 0..RUNS {
            let started = Instant::now();
            let reply = h.get(OVERVIEW, &admin).await;
            fastest = fastest.min(started.elapsed());
            assert_eq!(reply.status, 200, "{}", reply.body);
            body = reply.body;
        }
        eprintln!("{} overview: {fastest:?}", db.backend);

        assert_eq!(body["devices"]["total"], DEVICES);
        assert_eq!(body["devices"]["online"], ONLINE);
        assert_eq!(body["active_connections"], ONLINE * 2);
        assert!(body["connections_24h"].as_i64().unwrap() > ROWS / 3);
        assert!(body["failed_logins_24h"].as_i64().unwrap() > ROWS / 4);
        assert_eq!(body["recent_alarms"].as_array().unwrap().len(), 5);
        assert_eq!(body["client_versions"]["unknown"], DEVICES / 20);

        if db.backend == Backend::Sqlite {
            let budget = budget();
            assert!(
                fastest < budget,
                "overview took {fastest:?} (budget {budget:?})"
            );
        }
    })
    .await;
}
